```python
"""Graph utilities for shortest-path and reachability analysis."""
from typing import Dict, List, Tuple, Optional, Set
from dataclasses import dataclass
from heapq import heappush, heappop
from collections import deque


@dataclass
class Edge:
    src: int
    dst: int
    weight: float


class WeightedGraph:
    """Adjacency-list weighted directed graph."""
    def __init__(self):
        self.adj: Dict[int, List[Tuple[int, float]]] = {}
        self._edges: List[Edge] = []
        self._node_data: Dict[int, dict] = {}

    def add_node(self, node_id: int, **data):
        if node_id not in self.adj:
            self.adj[node_id] = []
        self._node_data[node_id] = data

    def add_edge(self, src: int, dst: int, weight: float = 1.0):
        self.add_node(src)
        self.add_node(dst)
        self.adj[src].append((dst, weight))
        self._edges.append(Edge(src, dst, weight))

    @property
    def nodes(self) -> Set[int]:
        return set(self.adj.keys())

    @property
    def edge_count(self) -> int:
        return len(self._edges)

    def neighbors(self, node: int) -> List[Tuple[int, float]]:
        return self.adj.get(node, [])

    def node_data(self, node: int) -> dict:
        return self._node_data.get(node, {})


def _dijkstra(
    graph: WeightedGraph,
    source: int,
    target: Optional[int] = None,
) -> Tuple[Dict[int, float], Dict[int, Optional[int]]]:
    """Single-source shortest paths with optional early stop at target."""
    dist: Dict[int, float] = {source: 0.0}
    prev: Dict[int, Optional[int]] = {source: None}
    heap: List[Tuple[float, int]] = [(0.0, source)]

    while heap:
        cur_dist, u = heappop(heap)
        if cur_dist != dist.get(u, float("inf")):
            continue

        if target is not None and u == target:
            break

        for v, w in graph.neighbors(u):
            new_dist = cur_dist + w
            if new_dist < dist.get(v, float("inf")):
                dist[v] = new_dist
                prev[v] = u
                heappush(heap, (new_dist, v))

    return dist, prev


def shortest_path(graph: WeightedGraph, source: int, target: int) -> Tuple[Optional[float], List[int]]:
    """Find shortest path from source to target.
    Returns (distance, path) or (None, []) if unreachable.
    """
    nodes = graph.nodes
    if source not in nodes or target not in nodes:
        return None, []

    dist, prev = _dijkstra(graph, source, target=target)
    if target not in dist:
        return None, []

    path: List[int] = []
    current: Optional[int] = target
    while current is not None:
        path.append(current)
        current = prev.get(current)
    path.reverse()
    return dist[target], path


def all_shortest_paths(graph: WeightedGraph, source: int) -> Dict[int, Tuple[float, List[int]]]:
    """Find shortest paths from source to all reachable nodes.
    Returns {node: (distance, path)}.
    """
    if source not in graph.nodes:
        return {}

    dist, prev = _dijkstra(graph, source)
    result: Dict[int, Tuple[float, List[int]]] = {}

    for node, d in dist.items():
        path: List[int] = []
        current: Optional[int] = node
        while current is not None:
            path.append(current)
            current = prev.get(current)
        path.reverse()
        result[node] = (d, path)

    return result


def k_nearest(graph: WeightedGraph, source: int, k: int) -> List[Tuple[int, float]]:
    """Find k nearest nodes to source by shortest path distance.
    Returns list of (node_id, distance) sorted by distance.
    """
    if source not in graph.nodes:
        return []
    if k == 0:
        return []

    # Preserve slicing behavior for negative k.
    if k < 0:
        all_paths = all_shortest_paths(graph, source)
        items = [(node, dist) for node, (dist, _) in all_paths.items() if node != source]
        items.sort(key=lambda x: x[1])
        return items[:k]

    dist: Dict[int, float] = {source: 0.0}
    heap: List[Tuple[float, int]] = [(0.0, source)]
    result: List[Tuple[int, float]] = []

    while heap and len(result) < k:
        cur_dist, u = heappop(heap)
        if cur_dist != dist.get(u, float("inf")):
            continue

        if u != source:
            result.append((u, cur_dist))
            if len(result) == k:
                break

        for v, w in graph.neighbors(u):
            new_dist = cur_dist + w
            if new_dist < dist.get(v, float("inf")):
                dist[v] = new_dist
                heappush(heap, (new_dist, v))

    return result


def is_reachable(graph: WeightedGraph, source: int, target: int) -> bool:
    """Check if target is reachable from source."""
    nodes = graph.nodes
    if source not in nodes or target not in nodes:
        return False
    if source == target:
        return True

    q = deque([source])
    visited = {source}

    while q:
        u = q.popleft()
        for v, _ in graph.neighbors(u):
            if v == target:
                return True
            if v not in visited:
                visited.add(v)
                q.append(v)

    return False


def connected_components(graph: WeightedGraph) -> List[Set[int]]:
    """Find weakly connected components (treating edges as undirected)."""
    nodes = graph.nodes
    if not nodes:
        return []

    undirected: Dict[int, Set[int]] = {n: set() for n in nodes}
    for src, nbrs in graph.adj.items():
        for dst, _ in nbrs:
            undirected[src].add(dst)
            undirected[dst].add(src)

    visited: Set[int] = set()
    components: List[Set[int]] = []

    for node in nodes:
        if node in visited:
            continue

        comp: Set[int] = set()
        q = deque([node])
        visited.add(node)

        while q:
            u = q.popleft()
            comp.add(u)
            for v in undirected[u]:
                if v not in visited:
                    visited.add(v)
                    q.append(v)

        components.append(comp)

    return components
